#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_delete_bt_node_with_only_left_child(void) {
    /* Path 15 conditions:
     * 1. *root != NULL (tree not empty)
     * 2. temp != NULL (node found in search loop)
     * 3. temp->data == ele (element matches)
     * 4. temp != NULL after loop (node exists)
     * 5. temp->llink != NULL && temp->rlink == NULL (node has only left child)
     * 6. temp != *root (node is not root)
     * 7. prev->llink != temp (node is not left child of parent)
     * 8. prev->rlink == temp (node is right child of parent)
     * 
     * This path deletes a node that:
     * - Has only a left child
     * - Is the right child of its parent
     * - Is not the root
     */

    /* Build a tree where node 30 has only a left child (20) and is right child of 10:
     *       10
     *         \n     *          30
     *         /
     *       20
     */
    int values[] = {10, 30, 20};
    node* root = helper_build_tree(values, 3);
    TEST_ASSERT_NOT_NULL(root);

    /* Verify initial tree structure */
    helper_assert_search_result(root, 30, 1);  /* Node 30 exists */
    helper_assert_search_result(root, 20, 1);  /* Node 20 exists */

    /* Delete node 30 (has only left child 20, is right child of 10) */
    delete_bt(&root, 30);

    /* Verify node 30 is deleted */
    helper_assert_search_result(root, 30, 0);

    /* Verify node 20 still exists and is now right child of 10 */
    helper_assert_search_result(root, 20, 1);
    helper_assert_search_result(root, 10, 1);

    /* Verify tree structure after deletion:
     *       10
     *         \n     *          20
     */
    helper_assert_tree_inorder(root, "10 20 ");
    helper_assert_tree_preorder(root, "10 20 ");

    /* Cleanup */
    helper_free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_delete_bt_node_with_only_left_child);
    return UNITY_END();
}

